offline.unsubscribe(offlineHandle)
offline.online(true)
await Promise.resolve()
if (calls !== 0) throw new Error(`detached offline attempt invoked ${calls} times`)
if (offline.snapshot('central').fetchStatus !== 'idle') throw new Error('detached offline attempt remained active')

let resolve
let inflightCalls = 0
