const inflightHandle = inflight.subscribe('harbor')
inflight.unsubscribe(inflightHandle)
resolve('cached')
await Promise.resolve()
if (inflightCalls !== 1 || inflight.snapshot('harbor').data !== 'cached') throw new Error('unconsumed inflight request no longer cached')

